    // rocks: a ledge under the figure and a few boulders, lit only by the
    // sky from above and behind
    let (rock_m, rock_lit) = {
        let mut form = paint::Form::new(f);
        let gy = |x: f32| fg(x);
        let solids = [
            paint::Sdf::block([722.0, gy(722.0) + 15.0, 0.0], [150.0, 32.0, 70.0], 5.0).turn([722.0, gy(722.0) + 15.0, 0.0], 0.15, 0.25, -0.03).rough(2.2, 22.0, 71, false),
            paint::Sdf::block([650.0, gy(650.0) + 24.0, 10.0], [60.0, 30.0, 50.0], 6.0).turn([650.0, gy(650.0) + 24.0, 10.0], -0.3, 0.3, 0.08).rough(2.0, 18.0, 72, false),
            paint::Sdf::ellipsoid([296.0, gy(296.0) + 5.0, 0.0], [27.0, 15.0, 20.0]).rough(2.5, 20.0, 73, false),
            paint::Sdf::ellipsoid([62.0, gy(62.0) + 6.0, 0.0], [36.0, 17.0, 24.0]).rough(3.0, 24.0, 74, false),
            paint::Sdf::ellipsoid([470.0, 655.0, 20.0], [30.0, 14.0, 20.0]).rough(2.5, 18.0, 75, false),
            paint::Sdf::ellipsoid([905.0, 646.0, 20.0], [40.0, 16.0, 24.0]).rough(3.0, 22.0, 76, false),
        ];
        for s in solids.iter() {
            form.add(s, 5.0);
        }
        form.light(paint::Light::new((-0.35, -1.0), -0.2).ambient(0.25));
        let m = form.mask(|_| 1.0).blur(0.6);
        let lit = form.mask(|s| s.shade.value);
        (m, lit)
    };
    if o.stage("rocks", &mut c, &mut rng) {
        let lit = &rock_lit;
        let tone = Fbm::new(77, 4, 16.0);
        let field = move |x: f32, y: f32| {
            let v = smoothstep(0.25, 0.8, lit.sample(x, y));
            let col = gradient(&[(0.0, hex("#231f1c")), (0.5, hex("#3d3833")), (1.0, hex("#79736c"))], v, Mix::Light);
            paint::shift(col, 0.03 * tone.get(x, y), 0.0, 0.0)
        };
        let lay = st.body().color(field).length(8.0, 26.0).coverage(3.5).clip(true).angle(|_, _| 0.1).cross(0.6).pressure(0.6, 0.85);
        c.work(&rock_m, &lay, 411);
        let det = st.detail().color(field).length(4.0, 12.0).coverage(1.5).cross(0.8);
        c.work(&rock_m, &det, 412);
    }

    // ---- the firs, painted on the dry sky and mist
    struct Fir {
        x: f32,
        base: f32,
        top: f32,
        w: f32,
        seed: u64,
    }
    let firs = [
        Fir { x: 166.0, base: fg(166.0) + 3.0, top: 286.0, w: 34.0, seed: 501 },
        Fir { x: 224.0, base: fg(224.0) + 3.0, top: 368.0, w: 27.0, seed: 502 },
        Fir { x: 122.0, base: fg(122.0) + 3.0, top: 468.0, w: 16.0, seed: 503 },
        Fir { x: 256.0, base: fg(256.0) + 3.0, top: 492.0, w: 12.0, seed: 504 },
    ];
    // a fir's silhouette: at each height a half width that grows downward,
    // tier by tier (the branches droop, so each tier is widest at its foot)
    fn fir_half(fr: &Fir, y: f32) -> f32 {
        let h = ((y - fr.top) / (fr.base - fr.top)).clamp(0.0, 1.0);
        let tiers = 7.0 + (fr.base - fr.top) / 16.0;
        let tier = (h * tiers).fract();
        let n = paint::noise::rand01((y * 0.9) as i32, 3, fr.seed as u32);
        fr.w * h.powf(0.85) * (0.62 + 0.38 * tier) * (0.85 + 0.3 * n) + 0.6
    }
    let fir_m = {
        let fs: Vec<(f32, f32, f32, f32, u64)> = firs.iter().map(|fr| (fr.x, fr.base, fr.top, fr.w, fr.seed)).collect();
        Mask::from_fn(f, move |x, y| {
            let mut v: f32 = 0.0;
            for &(fx, base, top, w, seed) in fs.iter() {
                if y < top - 2.0 || y > base + 2.0 {
                    continue;
                }
                let fr = Fir { x: fx, base, top, w, seed };
                let hw = fir_half(&fr, y);
                v = v.max(smoothstep(hw + 0.8, hw - 0.8, (x - fx).abs()));
            }
            v
        })
    };
    if o.stage("firs", &mut c, &mut rng) {
        let dark = st.palette.paint(hex("#1d2320"), 0.12);
        let darker = st.palette.paint(hex("#171b19"), 0.12);
        for fr in firs.iter() {
            let mut r = Rng::new(fr.seed);
            let span = fr.base - fr.top;
            // the trunk
            let mut tr = paint::Held::new(paint::Tool { point: 0.9, ..paint::Tool::round_sable(2.6) }, fr.seed);
            tr.load(darker, 0.9);
            c.drag(&mut tr, &paint::Gesture::new(vec![(fr.x, fr.base + 2.0), (fr.x + 0.4, fr.top + 0.4 * span), (fr.x + 0.2, fr.top)]).pressure(0.8, 0.15).ramps(0.02, 0.5), None);
            // branches, top to bottom: from the trunk out and down, the tips
            // lifting a little
            let n = (span / 2.6) as usize;
            let mut br = paint::Held::new(paint::Tool { point: 0.8, ..paint::Tool::round_sable(2.2) }, fr.seed + 1);
            for i in 0..n {
                if i % 3 == 0 {
                    br.reload(dark, 0.8);
                }
                let yy = fr.top + span * (i as f32 + r.range(0.0, 0.8)) / n as f32;
                let hw = fir_half(fr, yy + 3.0);
                for side in [-1.0f32, 1.0] {
                    if r.range(0.0, 1.0) < 0.15 {
                        continue;
                    }
                    let l = hw * r.range(0.8, 1.1);
                    let droop = l * r.range(0.25, 0.45);
                    let pts = vec![
                        (fr.x + side * 0.5, yy),
                        (fr.x + side * 0.45 * l, yy + 0.55 * droop),
                        (fr.x + side * 0.85 * l, yy + droop),
                        (fr.x + side * l, yy + 0.8 * droop),
                    ];
                    let p0 = 0.35 + 0.35 * ((yy - fr.top) / span);
                    c.drag(&mut br, &paint::Gesture::new(pts).pressure(p0, 0.12).ramps(0.05, 0.4).shake(0.6), None);
                }
            }
        }
        // the hanging twigs: short hatched strokes falling from the branches,
        // held in the silhouette
        let fill = st.hatch().color(|_, _| hex("#1b201d")).angle(|_, _| 1.35).angle_jitter(0.25).length(3.0, 8.0).coverage(1.6).clip(true);
        c.work(&fir_m, &fill, 511);
    }

    // ---- the figure, from behind, on the ledge
    let fx = FIGURE_X;
    let fb = fg(FIGURE_X) + 0.5;
    let coat = Mask::from_shape(f, paint::Shape::new().smooth_poly(&[
        (fx - 5.4, fb - 40.5), (fx - 2.5, fb - 42.0), (fx + 2.5, fb - 42.0), (fx + 5.4, fb - 40.5),
        (fx + 6.3, fb - 36.0), (fx + 6.4, fb - 26.0), (fx + 7.4, fb - 16.0), (fx + 1.0, fb - 15.0), (fx - 6.8, fb - 16.0), (fx - 6.2, fb - 26.0), (fx - 6.3, fb - 36.0),
    ]));
    let legs = Mask::from_shape(f, paint::Shape::new()
        .poly(&[(fx - 4.4, fb - 17.0), (fx - 1.0, fb - 17.0), (fx - 1.6, fb - 0.5), (fx - 4.6, fb - 0.2)])
        .add(paint::Shape::new().poly(&[(fx + 1.0, fb - 17.0), (fx + 4.5, fb - 17.0), (fx + 4.8, fb - 0.2), (fx + 1.8, fb - 0.5)])));
    let head = Mask::from_shape(f, paint::Shape::new().ellipse(fx, fb - 45.2, 3.3, 3.9).add(paint::Shape::new().ellipse(fx - 0.2, fb - 48.4, 4.4, 1.5)));
    let figure = coat.clone().union(&legs).union(&head);
    if o.stage("figure", &mut c, &mut rng) {
        // a dark coat, darker legs and cap, laid with the sable
        let coat_col = |_: f32, y: f32| paint::color::mix(hex("#2c302e"), hex("#232624"), smoothstep(fg(FIGURE_X) - 40.0, fg(FIGURE_X) - 16.0, y), Mix::Light);
        let d1 = st.detail().color(coat_col).angle(|_, _| 1.57).length(3.0, 9.0).coverage(4.0).clip(true).threshold(0.05);
        c.work(&coat, &d1, 601);
        let d2 = st.detail().color(|_, _| hex("#1d1c1b")).angle(|_, _| 1.57).length(3.0, 8.0).coverage(4.0).clip(true).threshold(0.05);
        c.work(&legs.clone().union(&head), &d2, 602);
        // a staff held in the right hand, planted on the ledge
        let mut rg = paint::Held::new(st.line_tool(0.9), 603);
        rg.load(st.palette.paint(hex("#2a2521"), 0.15), 0.9);
        c.drag(&mut rg, &paint::Gesture::line((fx + 6.2, fb - 25.0), (fx + 12.5, fb + 0.5)).pressure(0.7, 0.6), None);
        // the sky light along the left of the shoulders and the cap
        let mut rim = paint::Held::new(paint::Tool { point: 1.0, ..paint::Tool::round_sable(1.0) }, 604);
        rim.load(st.palette.paint(hex("#6c6670"), 0.2), 0.6);
        c.drag(&mut rim, &paint::Gesture::new(vec![(fx - 3.0, fb - 41.8), (fx - 5.4, fb - 40.3), (fx - 6.1, fb - 36.0), (fx - 6.0, fb - 31.0)]).pressure(0.35, 0.1), None);
        c.drag(&mut rim, &paint::Gesture::new(vec![(fx - 4.2, fb - 49.0), (fx - 1.0, fb - 49.8), (fx + 2.5, fb - 49.4)]).pressure(0.3, 0.1), None);
    }

    // ---- grass along the crest, last, as fine upturning strokes
    if o.stage("grass", &mut c, &mut rng) {
        let mut r = Rng::new(701);
        let mut held = paint::Held::new(paint::Tool { point: 0.9, ..paint::Tool::round_sable(1.1) }, 702);
        let cols = [hex("#2e2b25"), hex("#3b352b"), hex("#5c5040"), hex("#6e5c43")];
        let mut x = -4.0;
        let mut k = 0;
        while x < 1004.0 {
            x += r.range(0.6, 2.4);
            // no grass on the rocks or at the figure's feet
            let y0 = fg(x) + r.range(0.5, 4.0);
            if rock_m.sample(x, y0 - 3.0) > 0.3 || (x - FIGURE_X).abs() < 12.0 {
                continue;
            }
            if k % 6 == 0 {
                let ci = if r.range(0.0, 1.0) < 0.2 { 2 + (r.range(0.0, 1.99) as usize) } else { r.range(0.0, 1.99) as usize };
                held.reload(st.palette.paint(cols[ci], 0.15), 0.6);
            }
            k += 1;
            let len = r.range(3.0, 11.0) * (0.6 + 0.4 * smoothstep(900.0, 0.0, (x - 400.0).abs()));
            let lean = r.range(-0.5, 0.5) + 0.15;
            let pts = vec![(x, y0), (x + lean * 0.4 * len, y0 - 0.55 * len), (x + lean * len, y0 - len)];
            c.drag(&mut held, &paint::Gesture::new(pts).pressure(0.45, 0.05).ramps(0.05, 0.7).shake(0.4), None);
        }
    }

    // ---- the moon: a thin crescent, lit on the side toward the set sun
    if o.stage("moon", &mut c, &mut rng) {
        let (mx, my) = MOON;
        let (dx, dy) = (SUN_X - mx, 420.0 - my);
        let dl = (dx * dx + dy * dy).sqrt();
        let (ux, uy) = (-dx / dl, -dy / dl);
        let r0 = 6.8;
        let cres = Mask::from_fn(f, move |x, y| {
            let a = ((x - mx).powi(2) + (y - my).powi(2)).sqrt();
            let b = ((x - mx - ux * 0.42 * r0).powi(2) + (y - my - uy * 0.42 * r0).powi(2)).sqrt();
            smoothstep(r0 + 0.4, r0 - 0.4, a) * smoothstep(r0 * 1.02 - 0.5, r0 * 1.02 + 0.5, b)
        });
        // a faint halo first, then the crescent in two touches of paint
        c.glaze(&paint::Pigment::semi(hex("#dfe0da")), None, move |x, y| {
            let a = ((x - mx).powi(2) + (y - my).powi(2)).sqrt();
            0.18 * (-(a / 22.0).powi(2)).exp()
        });
        let d = st.detail().color(|_, _| hex("#f3ecd2")).length(2.0, 6.0).coverage(5.0).clip(true).threshold(0.05).pressure(0.5, 0.7);
        c.work(&cres, &d, 801);
    }

    // ---- last: a dark glaze growing deeper toward the edges and corners,
    // sparing the moon (Friedrich's advice to Carus)
    if o.stage("last glaze", &mut c, &mut rng) {
        let hh = hgt;
        let (mx, my) = MOON;
        c.glaze(&paint::Pigment::transparent(hex("#4a4150")), None, move |x, y| {
            let u = (x / 1000.0 - 0.5) * 2.0;
            let v = (y / hh - 0.45) * 2.0;
            let r = (u * u * 0.8 + v * v).sqrt();
            let m = ((x - mx).powi(2) + (y - my).powi(2)).sqrt();
            0.55 * smoothstep(0.55, 1.45, r) * smoothstep(8.0, 40.0, m)
        });
    }

