        let lay = st.glaze(0.55).color(body).angle(|_, _| -0.02).length(40.0, 140.0).coverage(3.0).clip(true).threshold(0.15);
        c.work(&cloud_m, &lay, 351);
        let bl = st.blend().unwrap().angle(|_, _| 0.0).length(60.0, 160.0).pressure(0.2, 0.3).clip(false);
        c.work(&cloud_m.clone().blur(4.0).map(|v| (v * 3.0).min(1.0)), &bl, 352);
        c.dry();
        // the lit undersides
        let under = cloud_m.clone().subtract(&cloud_m.clone().map(|v| v).blur(0.1).offset(-1.2)).mul_fn(move |x, y| smoothstep(-1.0, 1.0, y - 0.0) * (0.3 + 0.7 * glow(x)));
        let lit = st.detail().color(|_, _| hex("#efc9a2")).angle(|_, _| 0.0).length(6.0, 20.0).coverage(1.2).clip(true).threshold(0.1).pressure(0.3, 0.5);
        c.work(&under, &lit, 353);
    }

